import{at as e,it as t,n,vt as r}from"./chunks/framework.B6nQ8gjX.js";var i=JSON.parse(`{"title":"额外参数说明","description":"","frontmatter":{},"headers":[],"relativePath":"zh/guide/extra-params.md","filePath":"zh/guide/extra-params.md"}`),a={name:`zh/guide/extra-params.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e(`<h1 id="额外参数说明" tabindex="-1">额外参数说明 <a class="header-anchor" href="#额外参数说明" aria-label="Permalink to “额外参数说明”">​</a></h1><p>本文档对应 Zotero PDF2zh <strong>v4.1.7</strong>（含此前版本功能）。</p><p>本文档介绍各个翻译服务的额外配置参数。额外参数用于设置不同服务的特定选项。</p><div class="tip custom-block"><p class="custom-block-title">参数格式</p><p>额外配置参数名需要与配置文件中的字段相同。在 Zotero 插件 LLM API 编辑器的「额外参数」中填写。打开编辑器后会列出当前服务支持的字段；点「添加参数」可从列表选择，也可手动输入未列出的字段。不填则使用上游默认值。不要默认打开 JSON mode。</p></div><hr><h2 id="openai-openai-兼容服务" tabindex="-1">OpenAI / OpenAI 兼容服务 <a class="header-anchor" href="#openai-openai-兼容服务" aria-label="Permalink to “OpenAI / OpenAI 兼容服务”">​</a></h2><h3 id="基础字段" tabindex="-1">基础字段 <a class="header-anchor" href="#基础字段" aria-label="Permalink to “基础字段”">​</a></h3><ul><li><code>openai_model</code> / <code>openai_compatible_model</code> - 模型名称</li><li><code>openai_base_url</code> / <code>openai_compatible_base_url</code> - API 地址</li><li><code>openai_api_key</code> / <code>openai_compatible_api_key</code> - API 密钥</li></ul><h3 id="额外字段" tabindex="-1">额外字段 <a class="header-anchor" href="#额外字段" aria-label="Permalink to “额外字段”">​</a></h3><table tabindex="0"><thead><tr><th>参数</th><th>说明</th><th>示例值</th></tr></thead><tbody><tr><td><code>openai_timeout</code> / <code>openai_compatible_timeout</code></td><td>请求超时秒数</td><td>600</td></tr><tr><td><code>openai_temperature</code> / <code>openai_compatible_temperature</code></td><td>控制随机性，0-1 之间</td><td>0.3</td></tr><tr><td><code>openai_send_temprature</code> / <code>openai_compatible_send_temperature</code></td><td>是否发送 temperature 参数</td><td>true</td></tr><tr><td><code>openai_reasoning_effort</code> / <code>openai_compatible_reasoning_effort</code></td><td>推理强度 (minimal/low/medium/high)</td><td>low</td></tr><tr><td><code>openai_send_reasoning_effort</code> / <code>openai_compatible_send_reasoning_effort</code></td><td>是否发送 reasoning effort 参数</td><td>true</td></tr><tr><td><code>openai_enable_json_mode</code> / <code>openai_compatible_enable_json_mode</code></td><td>是否启用 JSON mode，默认关闭</td><td>true</td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title">OpenAI 参数兼容拼写</p><p><code>pdf2zh_next</code> 为了兼容历史配置，原生 OpenAI 服务仍使用拼写为 <code>openai_send_temprature</code> 的字段；这是上游有意保留的兼容字段。Server 会自动迁移旧版插件曾使用的 <code>openai_send_temperature</code>，<code>openai_compatible_send_temperature</code> 则继续使用正常拼写。</p></div><h3 id="示例配置" tabindex="-1">示例配置 <a class="header-anchor" href="#示例配置" aria-label="Permalink to “示例配置”">​</a></h3><div class="language-text" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>openai_temperature=0.3</span></span>
<span class="line"><span>openai_send_temprature=true</span></span></code></pre></div><hr><h2 id="deepseek" tabindex="-1">DeepSeek <a class="header-anchor" href="#deepseek" aria-label="Permalink to “DeepSeek”">​</a></h2><p>DeepSeek V4 模型（包括 <code>deepseek-v4-pro</code> 和 <code>deepseek-v4-flash</code>）支持显式控制思考模式。由于开启思考会产生额外 reasoning token 与费用，Zotero PDF2zh 默认关闭 DeepSeek 思考模式。</p><h3 id="基础字段-1" tabindex="-1">基础字段 <a class="header-anchor" href="#基础字段-1" aria-label="Permalink to “基础字段”">​</a></h3><ul><li><code>deepseek_model</code> - 模型名称，例如 <code>deepseek-v4-pro</code> 或 <code>deepseek-v4-flash</code></li><li><code>deepseek_api_key</code> - API 密钥</li></ul><h3 id="额外字段-1" tabindex="-1">额外字段 <a class="header-anchor" href="#额外字段-1" aria-label="Permalink to “额外字段”">​</a></h3><table tabindex="0"><thead><tr><th>参数</th><th>说明</th><th>可选值 / 默认值</th></tr></thead><tbody><tr><td><code>deepseek_thinking_mode</code></td><td>是否开启 DeepSeek V4 思考模式</td><td><code>disabled</code> / <code>enabled</code>，默认 <code>disabled</code></td></tr><tr><td><code>deepseek_reasoning_effort</code></td><td>思考强度，仅在思考模式开启时生效</td><td><code>high</code> / <code>max</code>，开启后默认 <code>high</code></td></tr><tr><td><code>deepseek_enable_json_mode</code></td><td>是否启用 JSON mode</td><td>依 <code>pdf2zh_next</code> 配置</td></tr></tbody></table><p>这些值仍然使用插件原有的 <code>extraData</code> 保存和传递。下拉框只是帮助用户填写、校验字段，不是另一套协议。</p><h3 id="实际执行方式" tabindex="-1">实际执行方式 <a class="header-anchor" href="#实际执行方式" aria-label="Permalink to “实际执行方式”">​</a></h3><p><code>pdf2zh_next 2.9.0</code> 在 <code>DeepSeekSettings</code> 中新增了 <code>deepseek_thinking_mode</code> 和 <code>deepseek_reasoning_effort</code>，对应 CLI 参数为：</p><div class="language-text" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>deepseek_thinking_mode     -&gt; --deepseek-thinking-mode</span></span>
<span class="line"><span>deepseek_reasoning_effort  -&gt; --deepseek-reasoning-effort</span></span></code></pre></div><p>Zotero PDF2zh v4.1.0 起的保护流程（v4.1.1 相同）：</p><ol><li>插件通过 <code>extraData</code> 保存用户选择；</li><li>DeepSeek V4 没有显式设置时，Server 自动使用 <code>disabled</code>；</li><li>对 uv / conda / system Python，Server 从<strong>本次实际 Python 环境中已安装的 <code>pdf2zh_next</code> distribution metadata/source</strong>静态确认 Thinking capability，不启动重型 <code>pdf2zh_next --help</code>；</li><li>支持时，将用户选择转换为上游正式 CLI 参数；</li><li>默认不思考且 runtime 不支持思考控制时，去掉这些字段并放行翻译；</li><li>用户手动开启思考但 runtime 不支持时，在任何翻译 API 调用之前停止并提示更新；</li><li>Windows standalone exe 无法通过 Python distribution 静态检查时，才使用独立的 exe capability 检查；</li><li>非 DeepSeek V4 不发送这些 V4-only 参数。</li></ol><div class="warning custom-block"><p class="custom-block-title">为什么不执行 pdf2zh_next --help？</p><p><code>pdf2zh_next 2.9.0</code> 在 CLI 参数解析前可能加载 BabelDOC / high-level 模块，因此 <code>--help</code> 并不是轻量健康检查，在部分机器上可能需要很长时间。v4.1.0 的正常 Python 环境路径改为静态检查，避免把一个已经安装成功的环境误判成失败。</p></div><div class="warning custom-block"><p class="custom-block-title">版本与 BabelDOC 的区别</p><p>DeepSeek V4 thinking 控制由 <strong><code>pdf2zh_next</code> 运行时</strong>提供，而不是由 BabelDOC 版本决定。<code>pdf2zh_next 2.8.2</code> 没有这两个字段；<code>pdf2zh_next 2.9.0</code> 才加入。BabelDOC / PyMuPDF 主要影响 PDF 解析和依赖兼容性。</p></div><p>上游 CLI 示例：</p><div class="language-bash" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#62687b;--shiki-dark:#818e99;"># 推荐默认：关闭思考</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">uv</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pdf2zh_next</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> input.pdf</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --deepseek</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --deepseek-model</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> deepseek-v4-flash</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --deepseek-thinking-mode</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> disabled</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --output</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ./output</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#62687b;--shiki-dark:#818e99;"># 开启思考，并使用 high 强度</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">uv</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pdf2zh_next</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> input.pdf</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --deepseek</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --deepseek-model</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> deepseek-v4-flash</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --deepseek-thinking-mode</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> enabled</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --deepseek-reasoning-effort</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> high</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --output</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ./output</span></span></code></pre></div><hr><h2 id="deeplx-pdf2zh-1-x" tabindex="-1">DeepLX（pdf2zh 1.x） <a class="header-anchor" href="#deeplx-pdf2zh-1-x" aria-label="Permalink to “DeepLX（pdf2zh 1.x）”">​</a></h2><p>DeepLX 通过旧版 <code>pdf2zh</code> 引擎配置。<code>pdf2zh</code> 1.x 的 <code>DEEPLX_ACCESS_TOKEN</code> 值可以为空，但字段本身必须存在；当前版本会保留这个可选字段。</p><ul><li><code>DEEPLX_ENDPOINT</code>：DeepLX 自定义翻译端点，可填写为 Base URL。</li><li><code>DEEPLX_ACCESS_TOKEN</code>：可选访问 token，不需要时可留空。</li></ul><p>如果日志最终请求的是 <code>https://api.deepl.com/v2/translate</code>，请先确认实际服务选择的是 <code>deeplx</code> 而不是 <code>deepl</code>。</p><hr><h2 id="ollama" tabindex="-1">Ollama <a class="header-anchor" href="#ollama" aria-label="Permalink to “Ollama”">​</a></h2><table tabindex="0"><thead><tr><th>参数</th><th>说明</th><th>默认值</th></tr></thead><tbody><tr><td><code>num_predict</code></td><td>最大预测 token 数</td><td>2000</td></tr></tbody></table><h2 id="azure-openai" tabindex="-1">Azure OpenAI <a class="header-anchor" href="#azure-openai" aria-label="Permalink to “Azure OpenAI”">​</a></h2><table tabindex="0"><thead><tr><th>参数</th><th>说明</th></tr></thead><tbody><tr><td><code>azure_openai_api_version</code></td><td>API 版本</td></tr></tbody></table><h2 id="siliconflow" tabindex="-1">SiliconFlow <a class="header-anchor" href="#siliconflow" aria-label="Permalink to “SiliconFlow”">​</a></h2><table tabindex="0"><thead><tr><th>参数</th><th>说明</th></tr></thead><tbody><tr><td><code>siliconflow_enable_thinking</code></td><td>启用思考模式</td></tr><tr><td><code>siliconflow_send_enable_thinking_param</code></td><td>是否发送思考模式参数</td></tr><tr><td><code>siliconflow_enable_json_mode</code></td><td>是否启用 JSON mode，默认关闭</td></tr></tbody></table><h2 id="siliconflow-free" tabindex="-1">SiliconFlow Free <a class="header-anchor" href="#siliconflow-free" aria-label="Permalink to “SiliconFlow Free”">​</a></h2><table tabindex="0"><thead><tr><th>参数</th><th>说明</th></tr></thead><tbody><tr><td><code>siliconflow_free_enable_json_mode</code></td><td>是否启用 JSON mode，默认关闭</td></tr></tbody></table><h2 id="qwen-mt" tabindex="-1">Qwen MT <a class="header-anchor" href="#qwen-mt" aria-label="Permalink to “Qwen MT”">​</a></h2><table tabindex="0"><thead><tr><th>参数</th><th>说明</th></tr></thead><tbody><tr><td><code>ali_domains</code></td><td>Qwen MT 的领域/上下文提示</td></tr></tbody></table><h2 id="使用建议" tabindex="-1">使用建议 <a class="header-anchor" href="#使用建议" aria-label="Permalink to “使用建议”">​</a></h2><ol><li>布尔值使用 <code>true</code> / <code>false</code>。</li><li>可选参数不确定时留空，使用上游默认值。</li><li>服务 API 和模型参数会变化；遇到参数被拒绝时，应同时核对当前 <code>pdf2zh_next</code> 版本和上游文档。</li></ol><div class="info custom-block"><p class="custom-block-title">相关文档</p><ul><li><a href="/zh/guide/configuration.html">配置说明</a></li><li><a href="/zh/guide/package-update.html">翻译环境更新</a></li><li><a href="/zh/guide/faq/translation-service.html">翻译服务问题</a></li></ul></div>`,49)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};